69	pub enum WebWindowError {
70	    AlreadyOpen,
71	    ReopeningUnsupported,
72	    UnsupportedWindowKind(&'static str),
73	    /// Graphics initialization has not completed yet; retrying after it
74	    /// finishes (e.g. from the `Platform::run` callback) can succeed.
75	    GraphicsInitializationPending,
76	    /// Graphics initialization or an earlier window creation failed;
77	    /// retrying cannot succeed.
78	    GraphicsUnavailable,
79	}
