123	    pub fn new_with_backend(
124	        allow_multi_threading: bool,
125	        backend_preference: WebBackendPreference,
126	    ) -> Self {
127	        let browser_window =
128	            web_sys::window().expect("must be running in a browser window context");
129	        let dispatcher = Arc::new(WebDispatcher::new(
130	            browser_window.clone(),
131	            allow_multi_threading,
132	        ));
133	        let background_executor = BackgroundExecutor::new(dispatcher.clone());
134	        let foreground_executor = ForegroundExecutor::new(dispatcher.clone());
135	        let text_system = Arc::new(gpui_wgpu::CosmicTextSystem::new_without_system_fonts(
136	            "IBM Plex Sans",
137	        ));
138	        let fonts = BUNDLED_FONTS
139	            .iter()
140	            .map(|bytes| Cow::Borrowed(*bytes))
141	            .collect();
142	        if let Err(error) = text_system.add_fonts(fonts) {
143	            log::error!("failed to load bundled fonts: {error:#}");
144	        }
145	        let text_system: Arc<dyn PlatformTextSystem> = text_system;
146	        let active_display: Rc<dyn PlatformDisplay> =
147	            Rc::new(WebDisplay::new(browser_window.clone()));
148	
149	        let cursor_visible = Rc::new(Cell::new(true));
150	        let last_cursor_css = Rc::new(Cell::new("default"));
151	        let cursor_restore_listeners = cursor_restore_listeners(
152	            &browser_window,
153	            cursor_visible.clone(),
154	            last_cursor_css.clone(),
155	        );
156	
157	        Self {
158	            browser_window,
159	            dispatcher,
160	            background_executor,
161	            foreground_executor,
162	            text_system,
163	            active_window: Rc::new(RefCell::new(None)),
164	            active_display,
165	            callbacks: RefCell::new(WebPlatformCallbacks::default()),
166	            backend_preference,
167	            wgpu_context: Rc::new(RefCell::new(None)),
168	            prepared_window: Rc::new(RefCell::new(None)),
169	            window_lifecycle: Rc::new(Cell::new(WebWindowLifecycle::Available)),
170	            cursor_visible,
171	            last_cursor_css,
172	            _cursor_restore_listeners: cursor_restore_listeners,
173	        }
174	    }
