190	async fn initialize_graphics(
191	    browser_window: &web_sys::Window,
192	    preference: WebBackendPreference,
193	) -> anyhow::Result<(
194	    web_sys::HtmlCanvasElement,
195	    WgpuContext,
196	    wgpu::Surface<'static>,
197	)> {
198	    match preference {
199	        WebBackendPreference::Auto => {
200	            let webgpu_canvas = WebWindow::prepare_canvas(browser_window)?;
201	            let webgpu_result = if wgpu::util::is_browser_webgpu_supported().await {
202	                WgpuContext::new_web(&webgpu_canvas, WebBackendPreference::WebGpu).await
203	            } else {
204	                Err(anyhow::anyhow!(
205	                    "browser WebGPU probe did not return a usable adapter"
206	                ))
207	            };
208	            match webgpu_result {
209	                Ok(PreparedWebGraphics { context, surface }) => {
210	                    return Ok((webgpu_canvas, context, surface));
211	                }
212	                Err(webgpu_error) => {
213	                    let canvas: &web_sys::Element = webgpu_canvas.as_ref();
214	                    canvas.remove();
215	                    log::warn!(
216	                        "WebGPU initialization failed; falling back to WebGL2: {webgpu_error:#}"
217	                    );
218	
219	                    let webgl_canvas =
220	                        WebWindow::prepare_canvas(browser_window).map_err(|error| {
221	                            anyhow::anyhow!(
222	                                "WebGPU initialization failed: {webgpu_error:#}. \
223	                             Failed to prepare a replacement canvas for WebGL2: {error:#}"
224	                            )
225	                        })?;
226	                    match WgpuContext::new_web(&webgl_canvas, WebBackendPreference::WebGl).await {
227	                        Ok(PreparedWebGraphics { context, surface }) => {
228	                            Ok((webgl_canvas, context, surface))
229	                        }
230	                        Err(webgl_error) => {
231	                            let canvas: &web_sys::Element = webgl_canvas.as_ref();
232	                            canvas.remove();
233	                            Err(anyhow::anyhow!(
234	                                "No browser graphics backend could be initialized. \
235	                                 Tried WebGPU, then WebGL2. \
236	                                 WebGPU failure: {webgpu_error:#}. \
237	                                 WebGL2 failure: {webgl_error:#}"
238	                            ))
239	                        }
240	                    }
241	                }
242	            }
243	        }
244	        WebBackendPreference::WebGpu | WebBackendPreference::WebGl => {
245	            let backend_name = if preference == WebBackendPreference::WebGpu {
246	                "WebGPU"
247	            } else {
248	                "WebGL2"
249	            };
250	            let canvas = WebWindow::prepare_canvas(browser_window)?;
251	            match WgpuContext::new_web(&canvas, preference).await {
252	                Ok(PreparedWebGraphics { context, surface }) => Ok((canvas, context, surface)),
253	                Err(error) => {
254	                    let canvas: &web_sys::Element = canvas.as_ref();
255	                    canvas.remove();
256	                    Err(anyhow::anyhow!(
257	                        "No browser graphics backend could be initialized. \
258	                         Only {backend_name} was tried because the application requested \
259	                         it explicitly. {backend_name} failure: {error:#}"
260	                    ))
261	                }
262	            }
263	        }
264	    }
265	}
